// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(ts > 0);
        vm.assume(actor != address(c));
        uint256 amt = 10 ether;
        vm.warp(ts);
        vm.deal(actor, 2 * amt);

        // first call at time ts succeeds and must record ts as pastBlockTime
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: amt}("");
        assertTrue(ok1, "first call should succeed");

        // second call at the SAME timestamp must revert in the reference
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: amt}("");
        assertTrue(!ok2, "second call at same timestamp must revert");
    }
}
